            ['section' => 'Comprehension', 'type' => 'sequence', 'question_text' => 'Put the events of the story in order.', 'sequence_items' => ['Fifteen dollars unexpectedly comes into Mrs. Sommers\' hands', 'She lies awake planning careful spending for her children', 'Her tired hand rests on a pile of silk stockings', 'She buys a pair and changes into them upstairs', 'Shoes, gloves, a restaurant lunch and a play follow']],
            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each place to what happened there.', 'match_pairs' => [['left' => 'The glove counter', 'right' => 'A long-wristed kid glove was fitted'], ['left' => 'The restaurant', 'right' => 'She dined like a princess of royal blood'], ['left' => 'The theater', 'right' => 'She wept over the tragedy beside a gaudy woman']]],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'What did the man with keen eyes detect in Mrs. Sommers\' face on the cable car?', 'option_a' => 'A powerful longing that the car would never stop', 'option_b' => 'Hunger and regret over her spending', 'option_c' => 'Plans for her children\'s new shoes', 'option_d' => 'Nothing unusual at all', 'correct_option' => 'a'],
